    16→
    17→// Mock JWT generation (in production, use proper JWT library)
    18→function generateMockToken(userId: string, tenantId: string): string {
    19→  const payload = Buffer.from(JSON.stringify({ userId, tenantId, exp: Date.now() + 86400000 })).toString('base64');
    20→  return `mock.${payload}.signature`;
    21→}
