    79→   * POST /api/auth/callback - OAuth callback
    80→   */
    81→  @Post('/callback')
    82→  async callback(request: AuthRequest, reply: FastifyReply) {
    83→    // Mock OAuth callback - in production integrates with BankID/ID-porten
