     4→ */
     5→import Fastify, { type FastifyInstance, type FastifyRequest, type FastifyReply } from 'fastify';
     6→import cors from '@fastify/cors';
     7→import rateLimit from '@fastify/rate-limit';
     8→import 'reflect-metadata';
     9→import { container, type Constructor } from '../core/container';
    10→import { getControllerMetadata } from '../core/decorators';
    11→import { serializeError } from '../core/errors/problem-details';
    12→import {
    13→  globalRateLimitConfig,
    14→  authRateLimitConfig,
    15→  authEndpoints,
    16→} from '../core/middleware/rate-limit.middleware';
    17→
    18→export interface FastifyAdapterOptions {
    19→  logger?: boolean;
    20→  prefix?: string;
    21→  adapters?: any;
    22→}
    23→
    24→/**
    25→ * Create and configure Fastify app with registered controllers
    26→ */
    27→export async function createFastifyApp(
    28→  controllers: Constructor[],
    29→  options: FastifyAdapterOptions = {}
    30→): Promise<FastifyInstance> {
    31→  const app = Fastify({
    32→    logger: options.logger ?? false,
    33→    requestIdLogLabel: 'correlationId',
    34→  });
    35→
    36→  // Enable CORS for all origins
    37→  await app.register(cors, {
    38→    origin: '*', // Allow ALL origins
    39→    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    40→    allowedHeaders: '*', // Allow ALL headers
    41→  });
    42→
    43→  // Register rate limiting with dynamic limits based on route
    44→  // Global rate limit: 100 req/min, Auth endpoints: 5 req/min
    45→  await app.register(rateLimit, {
    46→    ...globalRateLimitConfig,
    47→    max: async (request) => {
    48→      // Apply stricter limit to authentication endpoints
    49→      const isAuthEndpoint = authEndpoints.some((endpoint) =>
    50→        request.url.startsWith(endpoint)
    51→      );
    52→      return isAuthEndpoint ? authRateLimitConfig.max : globalRateLimitConfig.max;
    53→    },
    54→    errorResponseBuilder: (request, context) => {
    55→      // Use auth-specific error for auth endpoints
    56→      const isAuthEndpoint = authEndpoints.some((endpoint) =>
    57→        request.url.startsWith(endpoint)
    58→      );
    59→      if (isAuthEndpoint && authRateLimitConfig.errorResponseBuilder) {
    60→        return authRateLimitConfig.errorResponseBuilder(request, context);
    61→      }
    62→      return globalRateLimitConfig.errorResponseBuilder
    63→        ? globalRateLimitConfig.errorResponseBuilder(request, context)
    64→        : {
    65→            type: 'https://digilist.no/errors/rate-limit-exceeded',
    66→            title: 'Too Many Requests',
    67→            status: 429,
    68→            detail: `Rate limit exceeded.`,
    69→            instance: request.url,
    70→          };
    71→    },
    72→  });
    73→
    74→  // Handle empty JSON bodies (fixes SDK sending Content-Type: application/json with no body)
    75→  app.addContentTypeParser('application/json', { parseAs: 'string' }, (req, body, done) => {
    76→    if (!body || body === '') {
    77→      done(null, {});
    78→      return;
    79→    }
    80→    try {
    81→      done(null, JSON.parse(body as string));
    82→    } catch (err) {
    83→      done(err as Error, undefined);
    84→    }
    85→  });
    86→
    87→  // Inject adapters into requests
    88→  if (options.adapters) {
    89→    app.decorateRequest('adapters', null);
    90→    app.decorateRequest('tenantId', null);
    91→    app.decorateRequest('userId', null);
    92→
    93→    app.addHook('onRequest', async (request: any) => {
    94→      request.adapters = options.adapters;
    95→      // Use Skien Kommune as default tenant for demo, or null for public access
    96→      request.tenantId = request.headers['x-tenant-id'] || null;
    97→      request.userId = request.headers['x-user-id'] || null;
    98→    });
    99→  }
   100→
   101→  // Request logging
   102→  if (options.adapters?.log) {
   103→    app.addHook('onRequest', async (request) => {
   104→      options.adapters.log.info('Request received', {
   105→        method: request.method,
   106→        url: request.url,
   107→        correlationId: request.id,
   108→      });
   109→    });
   110→
   111→    app.addHook('onResponse', async (request, reply) => {
   112→      options.adapters.log.info('Request completed', {
   113→        method: request.method,
   114→        url: request.url,
   115→        statusCode: reply.statusCode,
   116→        duration: reply.elapsedTime,
   117→      });
   118→    });
   119→  }
   120→
   121→  // Global error handler (RFC 7807)
   122→  app.setErrorHandler(async (error: Error, request: FastifyRequest, reply: FastifyReply) => {
   123→    options.adapters?.log?.error('Request error', {
   124→      error: error.message,
   125→      stack: error.stack,
   126→      correlationId: request.id,
   127→    });
   128→
   129→    const problemDetails = serializeError(error, request.id);
   130→    return reply
   131→      .status(problemDetails.status)
   132→      .header('Content-Type', 'application/problem+json')
   133→      .send(problemDetails);
   134→  });
