   160→    switch (route.method) {
   161→      case 'GET':
   162→        app.get(path, handler);
   163→        break;
   164→      case 'POST':
   165→        app.post(path, handler);
   166→        break;
   167→      case 'PUT':
   168→        app.put(path, handler);
   169→        break;
   170→      case 'PATCH':
   171→        app.patch(path, handler);
   172→        break;
   173→      case 'DELETE':
   174→        app.delete(path, handler);
   175→        break;
   176→    }
   177→  }
   178→}
   179→
   180→/**
   181→ * Join path segments, ensuring result starts with /
   182→ */
   183→function joinPaths(...paths: (string | undefined)[]): string {
   184→  const joined = paths
   185→    .filter(Boolean)
   186→    .map((p) => p!.replace(/^\/+|\/+$/g, ''))
   187→    .filter((p) => p.length > 0)
   188→    .join('/');
   189→  return joined ? `/${joined}` : '/';
   190→}
